// TradeActionInput Body of POST /me/transactions/{id}/actions (and the organization equivalent).
type TradeActionInput struct {
	Action TradeAction `json:"action"`

	// File File name of an attached document or proof.
	File *string `json:"file,omitempty"`
	Note *string `json:"note,omitempty"`

	// Qc For `confirm_receipt`.
	Qc *struct {
		// AcceptedQty Required when outcome is `partial`; between 1 and quantity - 1.
		AcceptedQty *float64  `json:"acceptedQty,omitempty"`
		Note        *string   `json:"note,omitempty"`
		Outcome     QcOutcome `json:"outcome"`
	} `json:"qc,omitempty"`

	// Review For `review`. Same as Review without `by` and `at`.
	Review *struct {
		Communication float64 `json:"communication"`
		Quality       float64 `json:"quality"`
		Rating        int     `json:"rating"`
		Text          string  `json:"text"`
		Timeliness    float64 `json:"timeliness"`
	} `json:"review,omitempty"`

	// Shipment For `ship` and `upload_proof`.
	Shipment *struct {
		Carrier     string    `json:"carrier"`
		DropPoint   string    `json:"dropPoint"`
		Quantity    float64   `json:"quantity"`
		ScheduledAt time.Time `json:"scheduledAt"`
	} `json:"shipment,omitempty"`

	// ShipmentId For `upload_proof`; the shipment being confirmed delivered.
	ShipmentId *string `json:"shipmentId,omitempty"`
}

// TradeParty defines model for TradeParty.
type TradeParty struct {
	Kind     TradePartyKind `json:"kind"`
	Name     string         `json:"name"`
	UserId   *string        `json:"userId,omitempty"`
	Verified bool           `json:"verified"`
}

// TradePartyKind defines model for TradeParty.Kind.
type TradePartyKind string

// TradeState defines model for TradeState.
type TradeState struct {
	// Agreement Whether each side accepted the agreement (Record<Role, boolean>).
	Agreement struct {
		Buyer    bool `json:"buyer"`
		Supplier bool `json:"supplier"`
	} `json:"agreement"`

	// OpenShipments Shipments scheduled or in transit (not delivered yet).
	OpenShipments int `json:"openShipments"`

	// Reviewed Whether each side already reviewed (Record<Role, boolean>).
	Reviewed struct {
		Buyer    bool `json:"buyer"`
		Supplier bool `json:"supplier"`
	} `json:"reviewed"`

	// Status Transaction lifecycle status.
	Status TransactionStatus `json:"status"`
	Terms  PaymentTerms      `json:"terms"`

	// UnscheduledQty Quantity not yet put on a shipment.
	UnscheduledQty float64 `json:"unscheduledQty"`
}

// Transaction defines model for Transaction.
type Transaction struct {
	AuctionId    *string   `json:"auctionId,omitempty"`
	Code         string    `json:"code"`
	Counterparty PartyRef  `json:"counterparty"`
	CreatedAt    time.Time `json:"createdAt"`
	DueAt        time.Time `json:"dueAt"`
	Id           string    `json:"id"`

	// Peer The same trade as seen by the other party, when they are a platform account.
	Peer *struct {
		TxId   string `json:"txId"`
		UserId string `json:"userId"`
	} `json:"peer,omitempty"`
	Quantity Quantity        `json:"quantity"`
	Role     TransactionRole `json:"role"`

	// Status Transaction lifecycle status.
	Status       TransactionStatus `json:"status"`
	Terms        *PaymentTerms     `json:"terms,omitempty"`
	Title        string            `json:"title"`
	TotalIdr     int               `json:"totalIdr"`
	UnitPriceIdr int               `json:"unitPriceIdr"`
	UpdatedAt    time.Time         `json:"updatedAt"`
}

// TransactionRole defines model for Transaction.Role.
type TransactionRole string

// TransactionDetail defines model for TransactionDetail.
type TransactionDetail struct {
	Agreement *struct {
		BuyerAcceptedAt    *time.Time `json:"buyerAcceptedAt,omitempty"`
		SupplierAcceptedAt *time.Time `json:"supplierAcceptedAt,omitempty"`
	} `json:"agreement,omitempty"`
	AuctionId    *string   `json:"auctionId,omitempty"`
	Code         string    `json:"code"`
	Counterparty PartyRef  `json:"counterparty"`
	CreatedAt    time.Time `json:"createdAt"`
	Delivery     struct {
		Address string     `json:"address"`
		Eta     *time.Time `json:"eta,omitempty"`
		Proof   *string    `json:"proof,omitempty"`
	} `json:"delivery"`
	Dispute *struct {
		// Evidence Evidence from either party (F6); the opening reason is the first entry.
		Evidence *[]struct {
			At   time.Time                          `json:"at"`
			By   TransactionDetailDisputeEvidenceBy `json:"by"`
			File *string                            `json:"file,omitempty"`
			Id   string                             `json:"id"`
			Name string                             `json:"name"`
			Text string                             `json:"text"`
		} `json:"evidence,omitempty"`
		OpenedAt time.Time `json:"openedAt"`
		Reason   string    `json:"reason"`

		// Status Dispute lifecycle status.
		Status DisputeStatus `json:"status"`
	} `json:"dispute,omitempty"`
	Documents []struct {
		At   time.Time                      `json:"at"`
		Id   string                         `json:"id"`
		Kind TransactionDetailDocumentsKind `json:"kind"`
		Name string                         `json:"name"`
	} `json:"documents"`
	DueAt time.Time `json:"dueAt"`

	// Group Part of an aggregated (collective) settlement.
	Group *struct {
		Id    string  `json:"id"`
		Label string  `json:"label"`
		Share float64 `json:"share"`
	} `json:"group,omitempty"`
	Id      string `json:"id"`
	Invoice *struct {
		DueAt    time.Time `json:"dueAt"`
		IssuedAt time.Time `json:"issuedAt"`
		Number   string    `json:"number"`
	} `json:"invoice,omitempty"`

	// MakerFeeRate Market maker commission rate for trades formed inside a market (0 otherwise).
	MakerFeeRate *float64 `json:"makerFeeRate,omitempty"`
	Payment      struct {
		PaidAt *time.Time                     `json:"paidAt,omitempty"`
		Status TransactionDetailPaymentStatus `json:"status"`
	} `json:"payment"`

	// Peer The same trade as seen by the other party, when they are a platform account.
	Peer *struct {
		TxId   string `json:"txId"`
		UserId string `json:"userId"`
	} `json:"peer,omitempty"`
	Qc *struct {
		AcceptedQty float64                    `json:"acceptedQty"`
		At          time.Time                  `json:"at"`
		Note        *string                    `json:"note,omitempty"`
		Outcome     TransactionDetailQcOutcome `json:"outcome"`
	} `json:"qc,omitempty"`
	Quantity Quantity `json:"quantity"`
	Reviews  *struct {
		Buyer    *Review `json:"buyer,omitempty"`
		Supplier *Review `json:"supplier,omitempty"`
	} `json:"reviews,omitempty"`
	Role      TransactionDetailRole `json:"role"`
	Shipments *[]Shipment           `json:"shipments,omitempty"`

	// Status Transaction lifecycle status.
	Status   TransactionStatus `json:"status"`
	Terms    *PaymentTerms     `json:"terms,omitempty"`
	Timeline []struct {
		At   *time.Time `json:"at,omitempty"`
		Note *string    `json:"note,omitempty"`

		// Status Transaction lifecycle status.
		Status TransactionStatus `json:"status"`
	} `json:"timeline"`
	Title        string    `json:"title"`
	TotalIdr     int       `json:"totalIdr"`
	UnitPriceIdr int       `json:"unitPriceIdr"`
	UpdatedAt    time.Time `json:"updatedAt"`
}

// TransactionDetailDisputeEvidenceBy defines model for TransactionDetail.Dispute.Evidence.By.
type TransactionDetailDisputeEvidenceBy string

// TransactionDetailDocumentsKind defines model for TransactionDetail.Documents.Kind.
type TransactionDetailDocumentsKind string

