// VerificationAction defines model for VerificationAction.
type VerificationAction string

// VerificationRequest defines model for VerificationRequest.
type VerificationRequest struct {
	Business string `json:"business"`
	Decision *struct {
		At   time.Time `json:"at"`
		By   string    `json:"by"`
		Note string    `json:"note"`
	} `json:"decision,omitempty"`

	// Documents What the uploaded documents say (OCR in the real BE). Labels that also appear in `form` are compared.
	Documents []struct {
		Fields   []LabeledValue `json:"fields"`
		FileName string         `json:"fileName"`
		Kind     DocKind        `json:"kind"`

		// Url Detail endpoint only, when the file is in object storage. Presigned GET URL for the reviewer, valid 5 minutes.
		Url *string `json:"url,omitempty"`
	} `json:"documents"`

	// Form What the applicant typed into the form.
	Form []LabeledValue `json:"form"`
	Id   string         `json:"id"`

	// Kind Business documents (default) or a person's KTP + selfie.
	Kind *VerificationRequestKind `json:"kind,omitempty"`

	// Nik Personal requests, detail endpoint only: the full NIK, decrypted for the reviewer. Never in lists, never stored in clear (`form` and OCR fields carry it masked).
	Nik   *string `json:"nik,omitempty"`
	Owner string  `json:"owner"`

	// Status Declared as `VerificationStatus` in features/admin/types.ts; renamed because org.ts exports an unrelated `VerificationStatus`.
	Status      AdminVerificationStatus `json:"status"`
	SubmittedAt time.Time               `json:"submittedAt"`
}

